mod resumable_tests{use super::*;#[test]fn receipt_marker_roundtrips(){let receipt=ToolchainReceipt{action:2,checkpoint:3,outcome:1,status:0,elapsed_ms:7,attempt:2,command_hash:11,toolchain_hash:12,target_hash:13,profile:1};assert_eq!(parse_receipt(&receipt_text(&receipt).expect("render")).expect("parse"),receipt);}#[test]fn typed_numeric_parser_preserves_bounds(){assert_eq!(parsed_u64("0","x").expect("zero"),0);assert_eq!(parsed_u64("+42","x").expect("plus"),42);assert!(parsed_u64("-1","x").is_err());assert!(parsed_u64("18446744073709551616","x").is_err());assert_eq!(parsed_u32("4294967295","x").expect("u32 max"),u32::MAX);assert!(parsed_u32("4294967296","x").is_err());assert_eq!(parsed_i32("-2147483648","x").expect("i32 min"),i32::MIN);assert_eq!(parsed_i32("+2147483647","x").expect("i32 max"),i32::MAX);assert!(parsed_i32("2147483648","x").is_err());assert!(parsed_i32("-2147483649","x").is_err());}#[test]fn run_checkpoint_is_not_executed_twice(){assert_eq!(EG(1,0),1);assert_eq!(EG(2,0),0);assert_eq!(EG(3,0),0);assert_eq!(EG(4,0),0);assert_eq!(EG(5,0),0);}#[test]fn shared_batch_plan_controls_phases(){assert_eq!(eoie_batch_plan_advance(0,0),1);assert_eq!(eoie_batch_plan_advance(1,1),2);assert_eq!(eoie_batch_plan_advance(2,2),3);assert_eq!(eoie_batch_plan_advance(3,4),5);assert_eq!(eoie_batch_plan_advance(0,2),-1);}#[test]fn resume_policy_is_spiral_owned(){assert_eq!(RR(4,3),1);assert_eq!(RR(4,1),0);}#[test]fn release_argument_is_compiled(){assert_eq!(word(13).expect("release token"),"--release");}}

